mapper.select:
SELECT
role_id,
industry_view_id,
industry_view_type,
view_type
FROM
sys_role_screen_ref
where
delete_flag = 0

    and role_id = #{roleId}


    and tenant_id = #{tenantId}


    and industry_code = #{industryCode}


    and app_ver_code = #{appVerCode}


    and industry_view_id = #{industryViewId}


    and industry_view_type = #{industryViewType}

SELECT a.industry_view_id, a.industry_view_type, a.view_type, a.group_id, a.attr, a.tab_name FROM ( SELECT t1.industry_view_id, t1.industry_view_type, t1.view_type, t2.group_id, t2.attr, t2.tab_name, t1.create_time as create_time, t2.sort as sort, t1.id as id FROM sys_role_screen_ref t1 LEFT JOIN screen_menu_conf t2 ON t1.tenant_id = t2.tenant_id and t1.industry_code = t2.industry_code and t1.app_ver_code = t2.app_ver_code and t1.industry_view_id = t2.industry_view_id and t1.industry_view_type = t2.industry_view_type and IFNULL(t1.view_type, 0) = IFNULL(t2.view_type, 0) WHERE t1.delete_flag = 0
and t1.tenant_id = #{tenantId}
and t1.industry_code = #{industryCode}
and t1.app_ver_code = #{appVerCode}
and t1.role_id in
#{item}
ORDER BY t1.create_time DESC, t2.sort ASC, t1.id ASC LIMIT 1000000 ) a GROUP BY a.industry_view_id, a.industry_view_type, a.view_type ORDER BY a.create_time DESC, a.sort ASC, a.id ASC

SELECT distinct role_id FROM sys_role_screen_ref WHERE delete_flag = 0
and tenant_id = #{tenantId}
and industry_code = #{industryCode}
and app_ver_code = #{appVerCode}
and role_id in
#{item}
ORDER BY create_time DESC

