update sys_role_screen_ref set delete_flag = 1,UPDATE_TIME = now(),UPDATE_BY = #{item.updateBy}
where 1 = 1

    and role_id = #{item.roleId}


    and industry_view_id = #{item.industryViewId}


    and industry_view_type = #{item.industryViewType}


    and view_type = #{item.viewType}

mapper.select:
SELECT DISTINCT a.* from ( SELECT DISTINCT a.industry_code, a.app_ver_code, b.tenant_id FROM vm_order_package b LEFT JOIN sys_industry_ver_conf a ON a.industry_code = b.industry_code AND a.app_ver_code = b.app_ver_code LEFT JOIN sys_industry_conf f ON a.industry_code = f.industry_code and f.delete_flag = 0 WHERE a.delete_flag = 0 and b.tenant_id = #{tenantId} and f.accept_node = #{platformCode} and a.accept_node = #{platformCode}
UNION
SELECT DISTINCT a.industry_code, a.app_ver_code, c.tenant_id FROM vm_order_package_his c LEFT JOIN sys_industry_ver_conf a ON a.industry_code = c.industry_code AND a.app_ver_code = c.app_ver_code LEFT JOIN sys_industry_conf f ON a.industry_code = f.industry_code and f.delete_flag = 0 WHERE a.delete_flag = 0 and c.tenant_id = #{tenantId} and f.accept_node = #{platformCode} and a.accept_node = #{platformCode} ) a
